import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class EducationalRound86E {

    public static final long MOD = 998244353L;
    public static final int MAX = (int)4e5 + 10;
    public static long[] fact;
    public static long[] invFact;

    public static void preCompute() {
        fact = new long[MAX];
        invFact = new long[MAX];
        fact[0] = fact[1] = invFact[0] = invFact[1] = 1L;
        for (int i = 2; i < MAX; i++) {
            fact[i] = (fact[i - 1] * (long)i) % MOD;
            invFact[i] = (invFact[i - 1] * modInverse(i, MOD)) % MOD;
        }
    }

    public static long nCr(int n, int r) {
        long res = fact[n] * invFact[r] % MOD;
        res = res * invFact[n - r] % MOD;
        return res;
    }

    public static long powMod(long a, long n) {
        if (n == 0) return 1L;
        long half = powMod(a, n / 2);
        half = half * half % MOD;
        if ((n & 1) == 1) half = half * a % MOD;
        return half;
    }

    public static void solve() {
        preCompute();
        int n = reader.nextInt();
        long k = reader.nextLong();
        if (k == 0) {
            writer.println(fact[n]);
            return;
        }
        if (n <= k) {
            writer.println(0);
            return;
        }
        long comb = nCr(n, (int)k);
        int cols = n - (int)k;
        long sum = 0L;
        for (int i = 0; i <= cols; i++) {
            long term = nCr(cols, i);
            term = term * powMod(cols - i, n) % MOD;
            if ((i & 1) == 1) {
                sum -= term;
                if (sum < 0) sum += MOD;
            } else {
                sum += term;
                if (sum >= MOD) sum -= MOD;
            }
        }
        writer.println((2L * ((comb * sum) % MOD)) % MOD);
    }

    public static void main(String[] args) {
        writer = new PrintWriter(new BufferedOutputStream(System.out));
        reader = new FastReader();
        solve();
        writer.close();
    }

    public static class Triplet {
        long gcd;
        long x;
        long y;

        Triplet(long gcd, long x, long y) {
            this.gcd = gcd;
            this.x = x;
            this.y = y;
        }
    }

    public static Triplet extendedEuclid(long a, long b) {
        if (a == 0) return new Triplet(b, 0, 1);
        Triplet t = extendedEuclid(b % a, a);
        long x = t.y - (b / a) * t.x;
        long y = t.x;
        return new Triplet(t.gcd, x, y);
    }

    public static long modInverse(long a, long m) {
        Triplet t = extendedEuclid(a, m);
        if (t.gcd != 1) return -1;
        return (t.x % m + m) % m;
    }

    public static FastReader reader;
    public static PrintWriter writer;

    public static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (Exception e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}
